update public.question_solutions set final_answer_markdown='Trocar a microarquitetura mantendo a mesma ISA.', explanation_markdown='A ISA é a interface visível ao software de baixo nível; a microarquitetura é uma implementação dessa interface. No caso apresentado, Compare o que o compilador assume — a ISA — com a forma interna de executá-la. Se as instruções preservam significado e efeitos, o binário continua válido. Logo, “Trocar a microarquitetura mantendo a mesma ISA.” é a conclusão correta. “Trocar a semântica das instruções da ISA.” não cumpre o critério técnico do caso: Se as instruções preservam significado e efeitos, o binário continua válido. “Remover o compilador.” não decorre do princípio aplicável: A ISA é a interface visível ao software de baixo nível; a microarquitetura é uma implementação dessa interface. “Alterar o resultado definido do programa.” deixa de executar a análise necessária: Compare o que o compilador assume — a ISA — com a forma interna de executá-la.' where question_id='40000000-0000-4000-8000-000000930001';
update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de níveis de abstração: Um compilador transforma um programa em C em código de máquina para uma ISA específica. Qual mudança pode ocorrer sem exigir que o código-fonte em C seja reescrito?', sort_order=1 where id='70000000-0000-4000-8000-000009300011';
update public.question_solution_steps set title='Recupere o princípio', content_markdown='A ISA é a interface visível ao software de baixo nível; a microarquitetura é uma implementação dessa interface.', sort_order=2 where id='70000000-0000-4000-8000-000009300012';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Compare o que o compilador assume — a ISA — com a forma interna de executá-la. No enunciado, Um compilador transforma um programa em C em código de máquina para uma ISA específica. Qual mudança pode ocorrer sem exigir que o código-fonte em C seja reescrito? Se as instruções preservam significado e efeitos, o binário continua válido.', sort_order=3 where id='70000000-0000-4000-8000-000009300013';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“Trocar a semântica das instruções da ISA.” não cumpre o critério técnico do caso: Se as instruções preservam significado e efeitos, o binário continua válido. “Remover o compilador.” não decorre do princípio aplicável: A ISA é a interface visível ao software de baixo nível; a microarquitetura é uma implementação dessa interface. “Alterar o resultado definido do programa.” deixa de executar a análise necessária: Compare o que o compilador assume — a ISA — com a forma interna de executá-la.', sort_order=4 where id='70000000-0000-4000-8000-000009300014';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “Trocar a microarquitetura mantendo a mesma ISA.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300015';

update public.question_solutions set final_answer_markdown='A microarquitetura.', explanation_markdown='Componentes e caminhos internos pertencem à implementação, desde que a interface arquitetural seja preservada. No caso apresentado, Pergunte se um programador que usa a ISA percebe uma instrução diferente. Os mesmos registradores, opcodes e resultados indicam compatibilidade arquitetural. Logo, “A microarquitetura.” é a conclusão correta. “A linguagem de alto nível.” não cumpre o critério técnico do caso: Os mesmos registradores, opcodes e resultados indicam compatibilidade arquitetural. “A ISA publicada ao programador.” não decorre do princípio aplicável: Componentes e caminhos internos pertencem à implementação, desde que a interface arquitetural seja preservada. “O formato do arquivo-fonte.” deixa de executar a análise necessária: Pergunte se um programador que usa a ISA percebe uma instrução diferente.' where question_id='40000000-0000-4000-8000-000000930002';
