update public.question_solution_steps set title='Recupere o princípio', content_markdown='Componentes e caminhos internos pertencem à implementação, desde que a interface arquitetural seja preservada.', sort_order=2 where id='70000000-0000-4000-8000-000009300022';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Pergunte se um programador que usa a ISA percebe uma instrução diferente. No enunciado, Uma equipe substitui uma ULA de 32 bits por outra mais rápida, sem alterar registradores, opcodes nem resultados das instruções. Que camada foi modificada? Os mesmos registradores, opcodes e resultados indicam compatibilidade arquitetural.', sort_order=3 where id='70000000-0000-4000-8000-000009300023';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“A linguagem de alto nível.” não cumpre o critério técnico do caso: Os mesmos registradores, opcodes e resultados indicam compatibilidade arquitetural. “A ISA publicada ao programador.” não decorre do princípio aplicável: Componentes e caminhos internos pertencem à implementação, desde que a interface arquitetural seja preservada. “O formato do arquivo-fonte.” deixa de executar a análise necessária: Pergunte se um programador que usa a ISA percebe uma instrução diferente.', sort_order=4 where id='70000000-0000-4000-8000-000009300024';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “A microarquitetura.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300025';

update public.question_solutions set final_answer_markdown='A implementação mudou, mas a ISA pode permanecer compatível.', explanation_markdown='Uma mesma instrução arquitetural pode ser realizada por diferentes sequências internas. No caso apresentado, Diferencie o contrato da instrução de sua realização física ou microprogramada. O resultado e os efeitos observáveis de MUL são o teste de compatibilidade. Logo, “A implementação mudou, mas a ISA pode permanecer compatível.” é a conclusão correta. “A instrução deixou de existir na ISA.” não cumpre o critério técnico do caso: O resultado e os efeitos observáveis de MUL são o teste de compatibilidade. “Todo programa precisa ser recompilado.” não decorre do princípio aplicável: Uma mesma instrução arquitetural pode ser realizada por diferentes sequências internas. “A CPU passou a ter outra linguagem de montagem.” deixa de executar a análise necessária: Diferencie o contrato da instrução de sua realização física ou microprogramada.' where question_id='40000000-0000-4000-8000-000000930003';
update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de níveis de abstração: Um processador passa a executar uma multiplicação por meio de várias microoperações internas em vez de uma unidade dedicada, mas a instrução MUL mantém seus operandos e resultado. Qual afirmação é correta?', sort_order=1 where id='70000000-0000-4000-8000-000009300031';
update public.question_solution_steps set title='Recupere o princípio', content_markdown='Uma mesma instrução arquitetural pode ser realizada por diferentes sequências internas.', sort_order=2 where id='70000000-0000-4000-8000-000009300032';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Diferencie o contrato da instrução de sua realização física ou microprogramada. No enunciado, Um processador passa a executar uma multiplicação por meio de várias microoperações internas em vez de uma unidade dedicada, mas a instrução MUL mantém seus operandos e resultado. Qual afirmação é correta? O resultado e os efeitos observáveis de MUL são o teste de compatibilidade.', sort_order=3 where id='70000000-0000-4000-8000-000009300033';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“A instrução deixou de existir na ISA.” não cumpre o critério técnico do caso: O resultado e os efeitos observáveis de MUL são o teste de compatibilidade. “Todo programa precisa ser recompilado.” não decorre do princípio aplicável: Uma mesma instrução arquitetural pode ser realizada por diferentes sequências internas. “A CPU passou a ter outra linguagem de montagem.” deixa de executar a análise necessária: Diferencie o contrato da instrução de sua realização física ou microprogramada.', sort_order=4 where id='70000000-0000-4000-8000-000009300034';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “A implementação mudou, mas a ISA pode permanecer compatível.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300035';

update public.question_solutions set final_answer_markdown='Porque ambos podem realizar a mesma transformação lógica, com custos e velocidades diferentes.', explanation_markdown='A escolha hardware/software é um trade-off de desempenho, custo, consumo e flexibilidade, não uma diferença de capacidade lógica. No caso apresentado, Avalie a transformação desejada e os custos de cada implementação. Uma solução em hardware pode acelerar uma função sem tornar a alternativa em software impossível. Logo, “Porque ambos podem realizar a mesma transformação lógica, com custos e velocidades diferentes.” é a conclusão correta. “Porque software não usa processador.” não cumpre o critério técnico do caso: Uma solução em hardware pode acelerar uma função sem tornar a alternativa em software impossível. “Porque hardware nunca precisa de energia.” não decorre do princípio aplicável: A escolha hardware/software é um trade-off de desempenho, custo, consumo e flexibilidade, não uma diferença de capacidade lógica. “Porque compiladores eliminam a necessidade de instruções.” deixa de executar a análise necessária: Avalie a transformação desejada e os custos de cada implementação.' where question_id='40000000-0000-4000-8000-000000930004';
