update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “Porque ambos podem realizar a mesma transformação lógica, com custos e velocidades diferentes.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300045';

update public.question_solutions set final_answer_markdown='Uma máquina virtual em um nível de abstração superior.', explanation_markdown='Uma máquina virtual define objetos e operações próprios, mesmo quando precisa ser interpretada por outro nível. No caso apresentado, Identifique qual conjunto de operações é apresentado ao programador daquele ambiente. O fato de bytecodes serem interpretados não os transforma em sinais elétricos da CPU. Logo, “Uma máquina virtual em um nível de abstração superior.” é a conclusão correta. “O circuito lógico da CPU.” não cumpre o critério técnico do caso: O fato de bytecodes serem interpretados não os transforma em sinais elétricos da CPU. “A frequência do clock físico.” não decorre do princípio aplicável: Uma máquina virtual define objetos e operações próprios, mesmo quando precisa ser interpretada por outro nível. “A disposição dos transistores.” deixa de executar a análise necessária: Identifique qual conjunto de operações é apresentado ao programador daquele ambiente.' where question_id='40000000-0000-4000-8000-000000930005';
update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de máquinas virtuais: Um interpretador executa bytecodes e oferece instruções que não existem diretamente no processador físico. O conjunto de bytecodes descreve principalmente:', sort_order=1 where id='70000000-0000-4000-8000-000009300051';
