update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “Uma máquina virtual em um nível de abstração superior.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300055';

update public.question_solutions set final_answer_markdown='B, pois seu tempo proporcional é menor.', explanation_markdown='Tempo de CPU é proporcional a instruções × CPI ÷ frequência. No caso apresentado, Compare $1,5/3$ com $0,8/2$, usando a mesma unidade de GHz. B resulta em $0,4$ contra $0,5$ unidades proporcionais de tempo. Logo, “B, pois seu tempo proporcional é menor.” é a conclusão correta. “A, pois 3 é maior que 2.” não cumpre o critério técnico do caso: B resulta em $0,4$ contra $0,5$ unidades proporcionais de tempo. “Empatam por executar o mesmo programa.” não decorre do princípio aplicável: Tempo de CPU é proporcional a instruções × CPI ÷ frequência. “Não é possível comparar CPI e clock.” deixa de executar a análise necessária: Compare $1,5/3$ com $0,8/2$, usando a mesma unidade de GHz.' where question_id='40000000-0000-4000-8000-000000930006';
