update public.question_solution_steps set title='Analise os distratores', content_markdown='“A, pois 3 é maior que 2.” não cumpre o critério técnico do caso: B resulta em $0,4$ contra $0,5$ unidades proporcionais de tempo. “Empatam por executar o mesmo programa.” não decorre do princípio aplicável: Tempo de CPU é proporcional a instruções × CPI ÷ frequência. “Não é possível comparar CPI e clock.” deixa de executar a análise necessária: Compare $1,5/3$ com $0,8/2$, usando a mesma unidade de GHz.', sort_order=4 where id='70000000-0000-4000-8000-000009300064';
