update public.question_solutions set final_answer_markdown='O tempo aumenta 4%.', explanation_markdown='Com clock constante, compare o produto entre número de instruções e CPI antes e depois. No caso apresentado, Calcule $0,80	imes1,30$ para o novo trabalho relativo. O produto é $1,04$, maior que o valor inicial $1,00$. Logo, “O tempo aumenta 4%.” é a conclusão correta. “O tempo reduz 20%.” não cumpre o critério técnico do caso: O produto é $1,04$, maior que o valor inicial $1,00$. “O tempo não muda.” não decorre do princípio aplicável: Com clock constante, compare o produto entre número de instruções e CPI antes e depois. “O tempo reduz 4%.” deixa de executar a análise necessária: Calcule $0,80	imes1,30$ para o novo trabalho relativo.' where question_id='40000000-0000-4000-8000-000000930007';
