update public.question_solutions set final_answer_markdown='Carregar o endereço-alvo no PC.', explanation_markdown='O PC determina o endereço da próxima instrução a buscar. No caso apresentado, Siga a consequência do desvio: a próxima instrução não é a sequencial. Sem atualizar o PC, a busca continuaria no caminho incorreto. Logo, “Carregar o endereço-alvo no PC.” é a conclusão correta. “Copiar o opcode para a ULA.” não cumpre o critério técnico do caso: Sem atualizar o PC, a busca continuaria no caminho incorreto. “Zerar todos os registradores.” não decorre do princípio aplicável: O PC determina o endereço da próxima instrução a buscar. “Escrever o alvo na cache.” deixa de executar a análise necessária: Siga a consequência do desvio: a próxima instrução não é a sequencial.' where question_id='40000000-0000-4000-8000-000000930009';
