update public.question_solution_steps set title='Aplique o critério', content_markdown='Siga a consequência do desvio: a próxima instrução não é a sequencial. No enunciado, Após buscar uma instrução, a CPU descobre que ela é um salto condicional tomado. Qual atualização é essencial antes da próxima busca? Sem atualizar o PC, a busca continuaria no caminho incorreto.', sort_order=3 where id='70000000-0000-4000-8000-000009300093';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“Copiar o opcode para a ULA.” não cumpre o critério técnico do caso: Sem atualizar o PC, a busca continuaria no caminho incorreto. “Zerar todos os registradores.” não decorre do princípio aplicável: O PC determina o endereço da próxima instrução a buscar. “Escrever o alvo na cache.” deixa de executar a análise necessária: Siga a consequência do desvio: a próxima instrução não é a sequencial.', sort_order=4 where id='70000000-0000-4000-8000-000009300094';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “Carregar o endereço-alvo no PC.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300095';

update public.question_solutions set final_answer_markdown='Usar R2 como endereço, ler memória e escrever o dado em R1.', explanation_markdown='Uma carga transfere para um registrador o conteúdo da posição apontada pelo operando de endereço. No caso apresentado, Separe registrador-base, endereço efetivo, leitura de memória e destino. O valor armazenado em R2 é endereço; o dado lido torna-se o novo valor de R1. Logo, “Usar R2 como endereço, ler memória e escrever o dado em R1.” é a conclusão correta. “Usar R1 como endereço e sobrescrever R2.” não cumpre o critério técnico do caso: O valor armazenado em R2 é endereço; o dado lido torna-se o novo valor de R1. “Somar R1 e R2 sem acessar memória.” não decorre do princípio aplicável: Uma carga transfere para um registrador o conteúdo da posição apontada pelo operando de endereço. “Ler R1 e gravar o resultado no PC.” deixa de executar a análise necessária: Separe registrador-base, endereço efetivo, leitura de memória e destino.' where question_id='40000000-0000-4000-8000-000000930010';
