update public.question_solution_steps set title='Recupere o princípio', content_markdown='Uma carga transfere para um registrador o conteúdo da posição apontada pelo operando de endereço.', sort_order=2 where id='70000000-0000-4000-8000-000009300102';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Separe registrador-base, endereço efetivo, leitura de memória e destino. No enunciado, Durante a execução de LOAD R1,[R2], qual sequência representa corretamente o uso lógico dos componentes? O valor armazenado em R2 é endereço; o dado lido torna-se o novo valor de R1.', sort_order=3 where id='70000000-0000-4000-8000-000009300103';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“Usar R1 como endereço e sobrescrever R2.” não cumpre o critério técnico do caso: O valor armazenado em R2 é endereço; o dado lido torna-se o novo valor de R1. “Somar R1 e R2 sem acessar memória.” não decorre do princípio aplicável: Uma carga transfere para um registrador o conteúdo da posição apontada pelo operando de endereço. “Ler R1 e gravar o resultado no PC.” deixa de executar a análise necessária: Separe registrador-base, endereço efetivo, leitura de memória e destino.', sort_order=4 where id='70000000-0000-4000-8000-000009300104';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “Usar R2 como endereço, ler memória e escrever o dado em R1.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300105';

update public.question_solutions set final_answer_markdown='Instruções simples e formatos regulares.', explanation_markdown='RISC favorece regularidade e operações simples, o que ajuda decodificação e pipeline. No caso apresentado, Procure a alternativa que descreve o conjunto de instruções, não a memória física. Registradores continuam centrais em arquiteturas RISC. Logo, “Instruções simples e formatos regulares.” é a conclusão correta. “Toda instrução acessa memória duas vezes.” não cumpre o critério técnico do caso: Registradores continuam centrais em arquiteturas RISC. “Ausência de registradores.” não decorre do princípio aplicável: RISC favorece regularidade e operações simples, o que ajuda decodificação e pipeline. “Instruções de tamanho sempre ilimitado.” deixa de executar a análise necessária: Procure a alternativa que descreve o conjunto de instruções, não a memória física.' where question_id='40000000-0000-4000-8000-000000930011';
