update public.question_solutions set final_answer_markdown='$5$.', explanation_markdown='A parte serial limita o ganho global: speedup máximo é $1/f_{serial}$. No caso apresentado, Faça o número de processadores tender ao infinito na expressão de Amdahl. Com fração serial $0,20$, o limite é $1/0,20=5$. Logo, “$5$.” é a conclusão correta. “$1,25$.” não cumpre o critério técnico do caso: Com fração serial $0,20$, o limite é $1/0,20=5$. “$4$.” não decorre do princípio aplicável: A parte serial limita o ganho global: speedup máximo é $1/f_{serial}$. “Infinito.” deixa de executar a análise necessária: Faça o número de processadores tender ao infinito na expressão de Amdahl.' where question_id='40000000-0000-4000-8000-000000930013';
update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de paralelismo: Um programa possui 80% de seu tempo perfeitamente paralelizável e 20% inevitavelmente serial. Pelo limite de Amdahl, qual é o ganho máximo com infinitos processadores?', sort_order=1 where id='70000000-0000-4000-8000-000009300131';
update public.question_solution_steps set title='Recupere o princípio', content_markdown='A parte serial limita o ganho global: speedup máximo é $1/f_{serial}$.', sort_order=2 where id='70000000-0000-4000-8000-000009300132';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Faça o número de processadores tender ao infinito na expressão de Amdahl. No enunciado, Um programa possui 80% de seu tempo perfeitamente paralelizável e 20% inevitavelmente serial. Pelo limite de Amdahl, qual é o ganho máximo com infinitos processadores? Com fração serial $0,20$, o limite é $1/0,20=5$.', sort_order=3 where id='70000000-0000-4000-8000-000009300133';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“$1,25$.” não cumpre o critério técnico do caso: Com fração serial $0,20$, o limite é $1/0,20=5$. “$4$.” não decorre do princípio aplicável: A parte serial limita o ganho global: speedup máximo é $1/f_{serial}$. “Infinito.” deixa de executar a análise necessária: Faça o número de processadores tender ao infinito na expressão de Amdahl.', sort_order=4 where id='70000000-0000-4000-8000-000009300134';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “$5$.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300135';

