update public.question_solutions set final_answer_markdown='$64$ KiB.', explanation_markdown='Com $n$ linhas de endereço existem $2^n$ posições; cada posição contém um byte. No caso apresentado, Calcule $2^{16}$ e converta bytes para KiB. $2^{16}=65536$ bytes, isto é, $64$ KiB. Logo, “$64$ KiB.” é a conclusão correta. “$16$ bytes.” não cumpre o critério técnico do caso: $2^{16}=65536$ bytes, isto é, $64$ KiB. “$32$ KiB.” não decorre do princípio aplicável: Com $n$ linhas de endereço existem $2^n$ posições; cada posição contém um byte. “$128$ KiB.” deixa de executar a análise necessária: Calcule $2^{16}$ e converta bytes para KiB.' where question_id='40000000-0000-4000-8000-000000930015';
