update public.question_solutions set final_answer_markdown='$0x78$.', explanation_markdown='Little-endian coloca o byte menos significativo no menor endereço. No caso apresentado, Separe a palavra em $12$, $34$, $56$ e $78$ e ordene os endereços crescentes. O menor endereço recebe o byte menos significativo. Logo, “$0x78$.” é a conclusão correta. “$0x12$.” não cumpre o critério técnico do caso: O menor endereço recebe o byte menos significativo. “$0x34$.” não decorre do princípio aplicável: Little-endian coloca o byte menos significativo no menor endereço. “$0x56$.” deixa de executar a análise necessária: Separe a palavra em $12$, $34$, $56$ e $78$ e ordene os endereços crescentes.' where question_id='40000000-0000-4000-8000-000000930016';
update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de ordem de bytes: Uma palavra de 32 bits $0x12345678$ é armazenada no endereço 100 em máquina little-endian. Qual byte fica no endereço 100?', sort_order=1 where id='70000000-0000-4000-8000-000009300161';
update public.question_solution_steps set title='Recupere o princípio', content_markdown='Little-endian coloca o byte menos significativo no menor endereço.', sort_order=2 where id='70000000-0000-4000-8000-000009300162';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Separe a palavra em $12$, $34$, $56$ e $78$ e ordene os endereços crescentes. No enunciado, Uma palavra de 32 bits $0x12345678$ é armazenada no endereço 100 em máquina little-endian. Qual byte fica no endereço 100? O menor endereço recebe o byte menos significativo.', sort_order=3 where id='70000000-0000-4000-8000-000009300163';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“$0x12$.” não cumpre o critério técnico do caso: O menor endereço recebe o byte menos significativo. “$0x34$.” não decorre do princípio aplicável: Little-endian coloca o byte menos significativo no menor endereço. “$0x56$.” deixa de executar a análise necessária: Separe a palavra em $12$, $34$, $56$ e $78$ e ordene os endereços crescentes.', sort_order=4 where id='70000000-0000-4000-8000-000009300164';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “$0x78$.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300165';

update public.question_solutions set final_answer_markdown='Pode localizar e corrigir certos erros de um bit.', explanation_markdown='Paridade normalmente detecta uma classe de erros; códigos com bits redundantes podem identificar a posição de um erro simples. No caso apresentado, Compare detectar uma inconsistência com saber qual bit deve ser corrigido. Correção de um bit não implica correção universal de falhas múltiplas. Logo, “Pode localizar e corrigir certos erros de um bit.” é a conclusão correta. “Elimina a necessidade de memória.” não cumpre o critério técnico do caso: Correção de um bit não implica correção universal de falhas múltiplas. “Aumenta automaticamente o clock.” não decorre do princípio aplicável: Paridade normalmente detecta uma classe de erros; códigos com bits redundantes podem identificar a posição de um erro simples. “Impede qualquer erro de múltiplos bits.” deixa de executar a análise necessária: Compare detectar uma inconsistência com saber qual bit deve ser corrigido.' where question_id='40000000-0000-4000-8000-000000930017';
