update public.question_solution_steps set title='Aplique o critério', content_markdown='Pense no padrão de acesso sequencial a vetores ou instruções. No enunciado, Por que caches usam blocos, e não transferem sempre um único byte? Transferir uma linha ajuda acessos próximos, embora não garanta hit em todos eles.', sort_order=3 where id='70000000-0000-4000-8000-000009300183';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“Para eliminar a RAM.” não cumpre o critério técnico do caso: Transferir uma linha ajuda acessos próximos, embora não garanta hit em todos eles. “Para tornar endereços desnecessários.” não decorre do princípio aplicável: Dados próximos no endereço tendem a ser acessados juntos; um bloco traz essa vizinhança. “Para impedir leituras repetidas.” deixa de executar a análise necessária: Pense no padrão de acesso sequencial a vetores ou instruções.', sort_order=4 where id='70000000-0000-4000-8000-000009300184';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “Para aproveitar a localidade espacial de dados próximos.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300185';

update public.question_solutions set final_answer_markdown='4 ns.', explanation_markdown='AMAT = tempo de hit + taxa de miss × penalidade de miss. No caso apresentado, Use taxa de miss $0,05$ na parcela adicional. $2+0,05	imes40=4$ ns. Logo, “4 ns.” é a conclusão correta. “2 ns.” não cumpre o critério técnico do caso: $2+0,05	imes40=4$ ns. “40 ns.” não decorre do princípio aplicável: AMAT = tempo de hit + taxa de miss × penalidade de miss. “42 ns.” deixa de executar a análise necessária: Use taxa de miss $0,05$ na parcela adicional.' where question_id='40000000-0000-4000-8000-000000930019';
update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de cache: Uma cache tem taxa de hit de 95%, tempo de hit 2 ns e penalidade de miss 40 ns. Qual AMAT aproxima melhor o tempo médio?', sort_order=1 where id='70000000-0000-4000-8000-000009300191';
update public.question_solution_steps set title='Recupere o princípio', content_markdown='AMAT = tempo de hit + taxa de miss × penalidade de miss.', sort_order=2 where id='70000000-0000-4000-8000-000009300192';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Use taxa de miss $0,05$ na parcela adicional. No enunciado, Uma cache tem taxa de hit de 95%, tempo de hit 2 ns e penalidade de miss 40 ns. Qual AMAT aproxima melhor o tempo médio? $2+0,05	imes40=4$ ns.', sort_order=3 where id='70000000-0000-4000-8000-000009300193';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“2 ns.” não cumpre o critério técnico do caso: $2+0,05	imes40=4$ ns. “40 ns.” não decorre do princípio aplicável: AMAT = tempo de hit + taxa de miss × penalidade de miss. “42 ns.” deixa de executar a análise necessária: Use taxa de miss $0,05$ na parcela adicional.', sort_order=4 where id='70000000-0000-4000-8000-000009300194';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “4 ns.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300195';

update public.question_solutions set final_answer_markdown='Percorrer colunas internas consecutivas dentro de cada linha.', explanation_markdown='Localidade espacial favorece endereços consecutivos, que costumam estar na mesma linha de cache. No caso apresentado, Relacione a ordem lógica do laço à disposição contígua dos elementos. Acessos adjacentes reutilizam o bloco recém-carregado. Logo, “Percorrer colunas internas consecutivas dentro de cada linha.” é a conclusão correta. “Saltar uma linha inteira a cada acesso.” não cumpre o critério técnico do caso: Acessos adjacentes reutilizam o bloco recém-carregado. “Acessar elementos em ordem aleatória.” não decorre do princípio aplicável: Localidade espacial favorece endereços consecutivos, que costumam estar na mesma linha de cache. “Alternar sempre entre extremos da matriz.” deixa de executar a análise necessária: Relacione a ordem lógica do laço à disposição contígua dos elementos.' where question_id='40000000-0000-4000-8000-000000930020';
update public.question_solution_steps set title='Delimite o problema', content_markdown='O enunciado apresenta esta situação de cache: Um laço percorre uma matriz por linhas em memória organizada por linhas. Qual ordem de acesso tende a produzir mais localidade espacial?', sort_order=1 where id='70000000-0000-4000-8000-000009300201';
update public.question_solution_steps set title='Recupere o princípio', content_markdown='Localidade espacial favorece endereços consecutivos, que costumam estar na mesma linha de cache.', sort_order=2 where id='70000000-0000-4000-8000-000009300202';
update public.question_solution_steps set title='Aplique o critério', content_markdown='Relacione a ordem lógica do laço à disposição contígua dos elementos. No enunciado, Um laço percorre uma matriz por linhas em memória organizada por linhas. Qual ordem de acesso tende a produzir mais localidade espacial? Acessos adjacentes reutilizam o bloco recém-carregado.', sort_order=3 where id='70000000-0000-4000-8000-000009300203';
update public.question_solution_steps set title='Analise os distratores', content_markdown='“Saltar uma linha inteira a cada acesso.” não cumpre o critério técnico do caso: Acessos adjacentes reutilizam o bloco recém-carregado. “Acessar elementos em ordem aleatória.” não decorre do princípio aplicável: Localidade espacial favorece endereços consecutivos, que costumam estar na mesma linha de cache. “Alternar sempre entre extremos da matriz.” deixa de executar a análise necessária: Relacione a ordem lógica do laço à disposição contígua dos elementos.', sort_order=4 where id='70000000-0000-4000-8000-000009300204';
update public.question_solution_steps set title='Verifique a conclusão', content_markdown='A alternativa correta é “Percorrer colunas internas consecutivas dentro de cada linha.”, pois é a única que respeita o princípio e o cenário apresentados.', sort_order=5 where id='70000000-0000-4000-8000-000009300205';

update public.question_solutions set final_answer_markdown='A CPU consultar continuamente um dispositivo lento para saber se ele terminou.', explanation_markdown='Interrupção permite que o dispositivo notifique a CPU quando um evento ocorre. No caso apresentado, Compare espera ativa com aviso assíncrono de conclusão. A CPU pode executar outro trabalho até ser interrompida. Logo, “A CPU consultar continuamente um dispositivo lento para saber se ele terminou.” é a conclusão correta. “A CPU usar registradores.” não cumpre o critério técnico do caso: A CPU pode executar outro trabalho até ser interrompida. “A memória ter endereços.” não decorre do princípio aplicável: Interrupção permite que o dispositivo notifique a CPU quando um evento ocorre. “O dispositivo transferir dados.” deixa de executar a análise necessária: Compare espera ativa com aviso assíncrono de conclusão.' where question_id='40000000-0000-4000-8000-000000930021';
