update public.question_solutions set final_answer_markdown='Mover o bloco entre dispositivo e memória com pouca intervenção da CPU.', explanation_markdown='DMA assume a transferência de dados e costuma sinalizar a conclusão por interrupção. No caso apresentado, Diferencie a preparação da operação pela CPU da movimentação repetitiva dos bytes. A CPU configura o DMA, mas não precisa copiar cada palavra individualmente. Logo, “Mover o bloco entre dispositivo e memória com pouca intervenção da CPU.” é a conclusão correta. “Executar cada instrução do processo.” não cumpre o critério técnico do caso: A CPU configura o DMA, mas não precisa copiar cada palavra individualmente. “Substituir a memória principal.” não decorre do princípio aplicável: DMA assume a transferência de dados e costuma sinalizar a conclusão por interrupção. “Decidir todos os desvios do programa.” deixa de executar a análise necessária: Diferencie a preparação da operação pela CPU da movimentação repetitiva dos bytes.' where question_id='40000000-0000-4000-8000-000000930022';
