update public.question_solutions set final_answer_markdown='Elas pertencem ao fluxo errado e não podem alterar o estado arquitetural.', explanation_markdown='Execução especulativa só é segura se efeitos de um caminho incorreto forem descartados. No caso apresentado, Siga o fluxo real após avaliar a condição e compare com o caminho buscado. Permitir que o caminho errado grave registradores ou memória produziria resultado incorreto. Logo, “Elas pertencem ao fluxo errado e não podem alterar o estado arquitetural.” é a conclusão correta. “Elas sempre são inválidas.” não cumpre o critério técnico do caso: Permitir que o caminho errado grave registradores ou memória produziria resultado incorreto. “A cache não pode conter instruções.” não decorre do princípio aplicável: Execução especulativa só é segura se efeitos de um caminho incorreto forem descartados. “O PC não pode ser atualizado.” deixa de executar a análise necessária: Siga o fluxo real após avaliar a condição e compare com o caminho buscado.' where question_id='40000000-0000-4000-8000-000000930025';
